problems.solution:
#include <stdio.h>

#define N 100

int main(void)
{
    int a[N];
    int n, i, max, pos;

    scanf("%d", &n);
    for (i = 0; i < n; i++)
        scanf("%d", &a[i]);

    max = a[0];
    pos = 0;
    for (i = 1; i < n; i++) {
        if (max < a[i]) {
            max = a[i];
            pos = i;
        }
    }
    printf("%d %d\n", max, pos + 1);

    for (i = n - 1; i >= 0; i--) {
        if (i == 0)
            printf("%d\n", a[i]);
        else
            printf("%d ", a[i]);
    }

    return 0;
}
